const WebSocket = require('ws');
const fs = require('fs');

class TestnetMonitor {
  constructor() {
    this.nodes = [
      { name: 'NODE-1', port: 3001, type: '검증자', status: 'UNKNOWN' },
      { name: 'NODE-2', port: 3002, type: '검증자', status: 'UNKNOWN' },
      { name: 'NODE-3', port: 3003, type: '사용자', status: 'UNKNOWN' }
    ];
    this.connections = new Map();
    this.lastUpdate = new Date();
    this.stats = {
      totalBlocks: 0,
      totalTransactions: 0,
      activeNodes: 0,
      networkLatency: 0
    };
  }

  async start() {
    console.log('🔍 백야 프로토콜 테스트넷 모니터 시작...\n');
    
    // 노드들에 연결 시도
    for (const node of this.nodes) {
      await this.connectToNode(node);
      await new Promise(resolve => setTimeout(resolve, 1000));
    }

    // 주기적 상태 업데이트
    setInterval(() => this.updateStatus(), 10000);
    
    // 실시간 모니터링 시작
    this.startRealTimeMonitoring();
  }

  async connectToNode(node) {
    try {
      const wsUrl = `ws://localhost:${node.port}`;
      console.log(`🔗 ${node.name} 연결 시도: ${wsUrl}`);
      
      const ws = new WebSocket(wsUrl);
      
      ws.on('open', () => {
        console.log(`✅ ${node.name} 연결 성공`);
        node.status = 'CONNECTED';
        this.connections.set(node.name, ws);
        
        // 인증 메시지 전송
        const authMessage = {
          type: 'auth',
          nodeId: 'MONITOR-' + Date.now(),
          timestamp: Date.now(),
          version: '1.0.0'
        };
        ws.send(JSON.stringify(authMessage));
      });

      ws.on('message', (data) => {
        try {
          const message = JSON.parse(data.toString());
          this.handleNodeMessage(node, message);
        } catch (error) {
          console.log(`⚠️ ${node.name} 메시지 파싱 오류:`, error.message);
        }
      });

      ws.on('close', () => {
        console.log(`❌ ${node.name} 연결 종료`);
        node.status = 'DISCONNECTED';
        this.connections.delete(node.name);
      });

      ws.on('error', (error) => {
        console.log(`⚠️ ${node.name} 연결 오류: ${error.message}`);
        node.status = 'ERROR';
      });

    } catch (error) {
      console.log(`❌ ${node.name} 연결 실패: ${error.message}`);
      node.status = 'FAILED';
    }
  }

  handleNodeMessage(node, message) {
    // 메시지 타입별 처리
    switch (message.type) {
      case 'newBlock':
        console.log(`📦 ${node.name}: 새 블록 감지 #${message.data?.index || 'N/A'}`);
        this.stats.totalBlocks++;
        break;
        
      case 'newTransaction':
        console.log(`💸 ${node.name}: 새 트랜잭션 감지`);
        this.stats.totalTransactions++;
        break;
        
      case 'heartbeat':
        node.lastHeartbeat = Date.now();
        break;
        
      case 'authResponse':
        if (message.success) {
          console.log(`🔐 ${node.name}: 인증 완료`);
        }
        break;
    }
  }

  updateStatus() {
    console.clear();
    console.log('🌐 백야 프로토콜 테스트넷 모니터');
    console.log('='.repeat(50));
    console.log(`📅 마지막 업데이트: ${new Date().toLocaleString()}`);
    console.log('');

    // 노드 상태
    console.log('🖥️  노드 상태:');
    this.stats.activeNodes = 0;
    
    this.nodes.forEach(node => {
      const statusIcon = this.getStatusIcon(node.status);
      const connectionInfo = node.status === 'CONNECTED' ? 
        `(${this.connections.has(node.name) ? '연결됨' : '연결 끊김'})` : '';
      
      console.log(`   ${statusIcon} ${node.name} [${node.type}] - 포트 ${node.port} ${connectionInfo}`);
      
      if (node.status === 'CONNECTED') {
        this.stats.activeNodes++;
      }
    });

    console.log('');

    // 네트워크 통계
    console.log('📊 네트워크 통계:');
    console.log(`   활성 노드: ${this.stats.activeNodes}/${this.nodes.length}`);
    console.log(`   총 블록 수: ${this.stats.totalBlocks}`);
    console.log(`   총 트랜잭션: ${this.stats.totalTransactions}`);
    console.log(`   네트워크 연결률: ${Math.round((this.stats.activeNodes / this.nodes.length) * 100)}%`);

    console.log('');

    // 연결 상태 매트릭스
    console.log('🔗 P2P 연결 매트릭스:');
    console.log('   [이 기능은 향후 구현 예정]');

    console.log('');
    console.log('💡 팁: Ctrl+C로 모니터를 종료할 수 있습니다');
  }

  getStatusIcon(status) {
    switch (status) {
      case 'CONNECTED': return '🟢';
      case 'DISCONNECTED': return '🔴';
      case 'ERROR': return '🟠';
      case 'FAILED': return '❌';
      default: return '⚪';
    }
  }

  startRealTimeMonitoring() {
    console.log('\n🔄 실시간 모니터링 시작...');
    console.log('새로운 블록과 트랜잭션이 실시간으로 표시됩니다.\n');
  }

  // 로그 저장
  saveLog(data) {
    const logEntry = {
      timestamp: new Date().toISOString(),
      ...data
    };

    const logFile = 'testnet/logs/monitor.log';
    fs.appendFileSync(logFile, JSON.stringify(logEntry) + '\n');
  }

  // 테스트넷 건강성 체크
  async healthCheck() {
    const results = {
      overall: 'HEALTHY',
      issues: []
    };

    // 노드 연결 체크
    const connectedNodes = this.nodes.filter(node => node.status === 'CONNECTED').length;
    if (connectedNodes < 2) {
      results.overall = 'UNHEALTHY';
      results.issues.push('연결된 노드가 2개 미만');
    }

    // 블록 생성 체크 (마지막 5분간)
    // [실제 구현에서는 블록 타임스탬프를 확인]

    return results;
  }

  cleanup() {
    console.log('\n🧹 모니터 정리 중...');
    
    for (const [nodeName, ws] of this.connections) {
      try {
        ws.close();
        console.log(`✅ ${nodeName} 연결 해제`);
      } catch (error) {
        console.log(`⚠️ ${nodeName} 연결 해제 오류: ${error.message}`);
      }
    }
    
    this.connections.clear();
    console.log('✅ 모니터 정리 완료');
  }
}

// 모니터 시작
const monitor = new TestnetMonitor();

// 프로세스 종료 시 정리
process.on('SIGINT', () => {
  monitor.cleanup();
  process.exit(0);
});

monitor.start().catch(error => {
  console.error('❌ 모니터 시작 실패:', error.message);
  process.exit(1);
});

const BlockchainCore = require('../src/blockchain/BlockchainCore');
const Transaction = require('../src/blockchain/Transaction');

// 노드 1 - 메인 검증자 노드
class TestnetNode1 {
  constructor() {
    this.blockchain = new BlockchainCore();
    this.nodeId = 'NODE-1';
    this.port = 3001;
    this.validatorDID = 'did:baekya:validator1000000000000000000000000000000000000000';
  }

  async start() {
    console.log('🚀 테스트넷 노드 1 시작...');
    
    try {
      // P2P 네트워크 시작
      const networkResult = await this.blockchain.p2pNetwork.start(this.port);
      if (!networkResult.success) {
        throw new Error(`네트워크 시작 실패: ${networkResult.error}`);
      }

      // 검증자 등록
      this.blockchain.pocConsensus.setContributionScore(this.validatorDID, 10000);
      console.log(`✅ 검증자 등록 완료: ${this.validatorDID.substring(0, 20)}...`);

      // 초기 테스트 잔액 설정
      this.setupInitialBalances();

      // 주기적으로 테스트 트랜잭션 생성
      this.startTransactionGenerator();

      console.log(`🌟 노드 1 준비 완료 - 포트: ${this.port}`);
      console.log(`📍 노드 ID: ${this.blockchain.p2pNetwork.nodeId.substring(0, 16)}...`);

    } catch (error) {
      console.error('❌ 노드 1 시작 실패:', error.message);
      process.exit(1);
    }
  }

  // 초기 잔액 설정
  setupInitialBalances() {
    const testDIDs = [
      'did:baekya:test1000000000000000000000000000000000000000',
      'did:baekya:test2000000000000000000000000000000000000000',
      'did:baekya:test3000000000000000000000000000000000000000'
    ];

    testDIDs.forEach((did, index) => {
      this.blockchain.setBalance(did, (index + 1) * 1000, 'B-Token');
    });

    console.log('💰 초기 테스트 잔액 설정 완료');
  }

  // 테스트 트랜잭션 생성기
  startTransactionGenerator() {
    let transactionCount = 0;
    
    setInterval(() => {
      try {
        transactionCount++;
        
        // 랜덤 트랜잭션 생성
        const fromDID = `did:baekya:test${Math.floor(Math.random() * 3) + 1}000000000000000000000000000000000000000`;
        const toDID = `did:baekya:test${Math.floor(Math.random() * 3) + 1}000000000000000000000000000000000000000`;
        const amount = Math.floor(Math.random() * 100) + 10;

        if (fromDID !== toDID) {
          const transaction = new Transaction(fromDID, toDID, amount, 'B-Token');
          transaction.sign(`test-key-${transactionCount}`);

          const result = this.blockchain.addTransaction(transaction);
          if (result.success) {
            console.log(`📝 테스트 트랜잭션 생성 #${transactionCount}: ${amount} B-Token`);
            
            // 트랜잭션이 5개 이상 쌓이면 블록 마이닝
            if (this.blockchain.pendingTransactions.length >= 5) {
              this.mineBlock();
            }
          }
        }
      } catch (error) {
        console.error('❌ 트랜잭션 생성 실패:', error.message);
      }
    }, 10000); // 10초마다 트랜잭션 생성
  }

  // 블록 마이닝
  async mineBlock() {
    try {
      console.log('⛏️ 블록 마이닝 시작...');
      
      const transactions = this.blockchain.pendingTransactions.slice(0, 5);
      const block = this.blockchain.createBlock(transactions, this.validatorDID);
      
      const result = this.blockchain.addBlock(block);
      if (result.success) {
        console.log(`✅ 블록 #${block.index} 마이닝 완료 - ${transactions.length}개 트랜잭션 포함`);
        
        // 네트워크에 새 블록 브로드캐스트
        this.blockchain.p2pNetwork.broadcastBlock(block.toJSON());
      }
    } catch (error) {
      console.error('❌ 블록 마이닝 실패:', error.message);
    }
  }

  // 노드 상태 출력
  getStatus() {
    const networkStatus = this.blockchain.p2pNetwork.getNetworkStatus();
    const chainLength = this.blockchain.chain.length;
    const pendingTxs = this.blockchain.pendingTransactions.length;

    return {
      nodeId: this.nodeId,
      port: this.port,
      chainLength,
      pendingTransactions: pendingTxs,
      connectedPeers: networkStatus.peerCount,
      lastBlock: this.blockchain.getLatestBlock().hash.substring(0, 16) + '...'
    };
  }
}

